@Service
@Transactional(readOnly = true)
@RequiredArgsConstructor
public class ItemService {

    private final ItemRepository itemRepository;            // Data JPA + Querydsl
    private final ItemQueryRepository itemQueryRepository;  // 화면 전용 DTO
    private final ItemStatRepository itemStatRepository;    // JdbcTemplate

    @Transactional
    public Item save(Item item) {
        return itemRepository.save(item);
    }

    public List<Item> search(ItemSearchCond cond) {
        return itemRepository.search(cond);
    }

    public List<ItemListDto> listScreen(ItemSearchCond cond, Pageable pageable) {
        return itemQueryRepository.findListDto(cond, pageable);
    }

    public List<CategoryStat> stats() {
        return itemStatRepository.categoryTop3();
    }
}
